import {mountPilot,unmountPilot,liveConnections} from './pilot.js';
import {projectGrowth,roundTrip,signals} from './models.js';
const stocks=[
 {symbol:'VFV',name:'Vanguard S&P 500 Index ETF',market:'CA',price:148.72,change:.83,type:'ETF',signal:'Broad exposure',kind:'growth',color:'#8c473c',bg:'#f5e9e4',mark:'V',risk:'Equity risk',note:'Tracks large U.S. companies in a Canadian-listed fund. A CAD listing avoids a direct USD trade conversion, but does not remove underlying currency exposure.',caution:'Concentrated in U.S. equities. It can lose substantial value during a market decline.',seed:3},
 {symbol:'XEQT',name:'iShares Core Equity ETF Portfolio',market:'CA',price:34.81,change:.62,type:'ETF',signal:'Diversified',kind:'growth',color:'#3e5468',bg:'#eaf0f5',mark:'iS',risk:'Equity risk',note:'A fund-of-funds approach to global equities. Use it to research diversification across countries and companies.',caution:'An all-equity portfolio can still fall sharply. Diversification does not protect against all market losses.',seed:7},
 {symbol:'RY',name:'Royal Bank of Canada',market:'CA',price:174.36,change:.41,type:'Stock',signal:'Income research',kind:'income',color:'#355c9a',bg:'#e9f0fa',mark:'RY',risk:'Single company',note:'A starting point for researching bank earnings, capital strength, valuation, and dividend coverage.',caution:'Dividends are not guaranteed. A single bank creates exposure to one company and the financial sector.',seed:10},
 {symbol:'FTS',name:'Fortis Inc.',market:'CA',price:63.42,change:-.24,type:'Stock',signal:'Income research',kind:'income',color:'#767443',bg:'#f0f0e3',mark:'F',risk:'Single company',note:'Research a utility through debt costs, regulated earnings, capital spending, and dividend coverage.',caution:'Interest rates, debt levels, and regulatory decisions can affect earnings and share price.',seed:16},
 {symbol:'XIC',name:'iShares Core S&P/TSX Capped Composite',market:'CA',price:38.95,change:.55,type:'ETF',signal:'Canada exposure',kind:'value',color:'#5c7755',bg:'#edf2e7',mark:'iS',risk:'Country concentration',note:'A broad Canadian-equity research candidate. Compare holdings, sector weights, and the fund’s published costs.',caution:'Canadian equities have substantial financial and resources exposure. A domestic fund is not a globally diversified portfolio.',seed:4},
 {symbol:'VOO',name:'Vanguard S&P 500 ETF',market:'US',price:518.43,change:.79,type:'ETF',signal:'Broad exposure',kind:'growth',color:'#8c473c',bg:'#f5e9e4',mark:'V',risk:'Equity & FX risk',note:'U.S.-listed exposure to large American companies. Compare total currency costs with a Canadian-listed alternative.',caution:'Quotes are in USD. Currency conversion costs can materially affect a small investment.',seed:5},
 {symbol:'MSFT',name:'Microsoft Corporation',market:'US',price:428.76,change:1.12,type:'Stock',signal:'Trend research',kind:'growth',color:'#5f796a',bg:'#eaf1eb',mark:'M',risk:'Single company & FX',note:'Research business growth alongside cash flow, valuation, and concentration risk.',caution:'A growing business can still be a poor investment at a high price. This is an illustrative research entry, not a buy signal.',seed:11},
 {symbol:'SCHD',name:'Schwab U.S. Dividend Equity ETF',market:'US',price:28.47,change:-.15,type:'ETF',signal:'Income research',kind:'income',color:'#416a8b',bg:'#eaf1f6',mark:'S',risk:'Equity & FX risk',note:'Explore how dividend strategies select companies and how holdings differ from a broad market fund.',caution:'Distributions can change. Currency costs and withholding taxes may affect Canadian investors.',seed:9}
];
const $=s=>document.querySelector(s);const money=(v,currency='CAD')=>new Intl.NumberFormat('en-CA',{style:'currency',currency,maximumFractionDigits:2}).format(v);const num=v=>v.toLocaleString('en-CA',{maximumFractionDigits:2,minimumFractionDigits:2});let saved=[];try{const x=JSON.parse(localStorage.getItem('northstar-watchlist')||'[]');if(Array.isArray(x))saved=[...new Set(x.filter(s=>stocks.some(t=>t.symbol===s)))];}catch{}let market='CA';let currentPage='overview';const overview=$('#main').innerHTML;let toastTimer;
function path(values,w=200,h=40,pad=2){const min=Math.min(...values),range=Math.max(...values)-min||1;return values.map((v,i)=>`${i?'L':'M'}${(i*w/(values.length-1)).toFixed(1)},${(h-pad-(v-min)/range*(h-pad*2)).toFixed(1)}`).join(' ')}
function history(seed){return Array.from({length:61},(_,i)=>100+i*.11+Math.sin(i*.7+seed)*1.1+Math.cos(i*.29+seed)*1.7)}
function spark(seed,negative=false){return `<svg class="spark" viewBox="0 0 200 40" preserveAspectRatio="none" aria-hidden="true"><path d="${path(history(seed).slice(-32))}" fill="none" stroke="${negative?'#b28d72':'#86a66e'}" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg>`}
function renderMarket(){const cards=[['🇨🇦','S&P/TSX','PRIMARY','26,418.23','+0.55%',2,false],['🇺🇸','S&P 500','','5,842.47','+0.79%',5,false],['🇺🇸','NASDAQ','','18,726.82','+1.12%',11,false],['↔','CAD / USD','','0.7312','−0.08%',14,true]];$('#market-cards').innerHTML=cards.map(([flag,label,badge,value,change,seed,neg])=>`<article class="market-card"><div class="market-card-top"><span class="country">${flag}</span>${label}${badge?`<small>${badge}</small>`:''}</div><div class="market-values"><strong>${value}</strong><span class="change ${neg?'negative':''}">${change}</span></div>${spark(seed,neg)}<div class="market-caption"><span>${label==='CAD / USD'?'USD per 1 CAD':'Illustrative index level'}</span><span>SAMPLE</span></div></article>`).join('')}
function row(s,wide=false){return `<div class="security-row"><button class="security-identity" data-detail="${s.symbol}" aria-label="Research ${s.symbol}"><span class="ticker-logo" style="color:${s.color};background:${s.bg}">${s.mark}</span><span><strong>${s.symbol} <span style="color:#a0a798;font-size:9px;font-weight:400">${s.market==='CA'?'TSX':'US'}</span></strong><small>${s.name}</small></span></button><div class="price">$${num(s.price)}<small>${s.market==='CA'?'CAD':'USD'}</small></div><div class="change ${s.change<0?'negative':''}">${s.change>0?'+':''}${s.change.toFixed(2)}%</div><div><span class="signal ${s.kind}">${s.signal}</span></div>${wide?`<div>${s.type}</div>`:''}<button class="star-button ${saved.includes(s.symbol)?'saved':''}" data-save="${s.symbol}" aria-label="${saved.includes(s.symbol)?'Remove':'Save'} ${s.symbol} ${saved.includes(s.symbol)?'from':'to'} watchlist" aria-pressed="${saved.includes(s.symbol)}">${saved.includes(s.symbol)?'★':'☆'}</button></div>`}
function table(list,wide=false){return `<div class="${wide?'wide-table':''}"><div class="security-row security-head"><div>ASSET</div><div>PRICE</div><div>1D CHANGE</div><div>RESEARCH LENS</div>${wide?'<div>TYPE</div>':''}<span></span></div>${list.length?list.map(s=>row(s,wide)).join(''):'<div class="no-results">No matches. Try another symbol or filter.</div>'}</div>`}
function renderOpportunities(){$('#opportunity-list').innerHTML=table(stocks.filter(s=>market==='ALL'||s.market===market).slice(0,5));document.querySelectorAll('[data-market]').forEach(b=>{b.classList.toggle('selected',b.dataset.market===market);b.setAttribute('aria-pressed',b.dataset.market===market)})}
function updateCount(){$('#watch-count').textContent=saved.length}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function toggleSave(symbol){if(!stocks.some(s=>s.symbol===symbol))return;saved=saved.includes(symbol)?saved.filter(s=>s!==symbol):[...saved,symbol];let persisted=true;try{localStorage.setItem('northstar-watchlist',JSON.stringify(saved))}catch{persisted=false}updateCount();if(currentPage==='overview'&&$('#opportunity-list'))renderOpportunities();else if(currentPage==='discover')filterDiscovery();else if(currentPage==='watchlist')renderWatchlist();document.querySelectorAll(`[data-save="${symbol}"]`).forEach(b=>{b.classList.toggle('saved',saved.includes(symbol));b.setAttribute('aria-pressed',saved.includes(symbol));if(b.classList.contains('star-button'))b.textContent=saved.includes(symbol)?'★':'☆';else b.textContent=saved.includes(symbol)?'Remove from watchlist':'Add to watchlist'});notify(persisted?(saved.includes(symbol)?`${symbol} saved to your watchlist`:`${symbol} removed from your watchlist`):'Watchlist updated for this session; browser storage is unavailable.')}
function heading(eyebrow,title,description){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div></div>`}
function demoBanner(){return '<div class="data-banner"><span>ⓘ</span><p><strong>Illustrative data only.</strong> These prices and signals are synthetic examples, not current quotes or recommendations.</p><a href="#connections">View data status ↗</a></div>'}
function renderDiscover(){$('#main').innerHTML=heading('RESEARCH, WITH PERSPECTIVE','Discover your next question.','Explore Canadian and U.S. investments. Understand the idea, then investigate the evidence.')+demoBanner()+`<div class="search-controls"><input id="search" type="search" placeholder="Search a symbol or company…" aria-label="Search investments"><select id="market-filter" aria-label="Filter by market"><option value="CA">Canada · primary</option><option value="US">United States</option><option value="ALL">All markets</option></select><select id="type-filter" aria-label="Filter by asset type"><option value="ALL">All asset types</option><option value="ETF">ETFs</option><option value="Stock">Stocks</option></select></div><section class="panel" id="discovery-results"></section><p class="source-note">Select an asset to see its research rationale and an example of historical risk calculations. CAD and USD prices are kept in their native currencies.</p>`;filterDiscovery()}
function filterDiscovery(){const q=$('#search').value.trim().toLowerCase(),m=$('#market-filter').value,t=$('#type-filter').value;$('#discovery-results').innerHTML=table(stocks.filter(s=>(s.symbol+' '+s.name).toLowerCase().includes(q)&&(m==='ALL'||s.market===m)&&(t==='ALL'||s.type===t)),true)}
function renderWatchlist(){$('#main').innerHTML=heading('YOUR RESEARCH SHORTLIST','Keep the interesting ones close.','Your saved assets, stored in this browser. No brokerage account required.')+demoBanner()+(saved.length?`<section class="panel">${table(stocks.filter(s=>saved.includes(s.symbol)),true)}</section>`:`<section class="panel empty"><span class="mini-star">☆</span><h2>Your watchlist starts with curiosity.</h2><p>Save an asset from Discover to keep your research in one place.</p><a class="button dark" href="#discover">Discover investments ↗</a></section>`)}
function showDetail(symbol){const s=stocks.find(s=>s.symbol===symbol);if(!s)return;const metrics=signals(history(s.seed));$('#dialog-content').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${s.market==='CA'?'CANADA · TSX':'UNITED STATES'} · ${s.type.toUpperCase()}</p><h2>${s.symbol}</h2><p>${s.name}</p></div><button class="close-dialog" aria-label="Close asset details">×</button></div><div class="status-strip">Synthetic example · no live quote or validated opportunity</div><div class="detail-stats"><div class="detail-stat">Sample price<strong>$${num(s.price)}</strong>${s.market==='CA'?'CAD':'USD'}</div><div class="detail-stat">20-session return<strong>${metrics.momentum.toFixed(1)}%</strong>synthetic history</div><div class="detail-stat">Annualized volatility<strong>${metrics.volatility.toFixed(1)}%</strong>synthetic history</div></div><div class="detail-section"><h3>Why you might research it</h3><p>${s.note}</p></div><div class="detail-section"><h3>What could go wrong</h3><p>${s.caution}</p></div><div class="detail-section"><h3>How these numbers are calculated</h3><p>Return compares the last price with 20 sessions earlier. Volatility is the sample standard deviation of daily returns, multiplied by √252. The worst peak-to-trough drop in this synthetic 61-point series is ${Math.abs(metrics.drawdown).toFixed(1)}%. These are descriptive measures, not predictions. They omit dividends, fees, and taxes.</p></div><div class="detail-footer"><span class="risk-chip">${s.risk}</span><button class="button dark" data-save="${s.symbol}" aria-pressed="${saved.includes(s.symbol)}">${saved.includes(s.symbol)?'Remove from watchlist':'Add to watchlist'}</button></div>`;$('#detail').showModal()}
function renderLab(){$('#main').innerHTML=heading('THE INVESTING LAB','Give your money some perspective.','Try a few assumptions. Understand the role of time, contributions, and costs.')+`<div class="lab-grid"><section class="panel form-panel"><h2>Build a scenario</h2><div class="input-group"><label for="initial">Starting amount · CAD</label><input id="initial" type="number" value="250" min="0" max="10000000" step="25"></div><div class="input-group"><label for="monthly">Monthly contribution · CAD</label><input id="monthly" type="number" value="50" min="0" max="100000" step="10"></div><div class="input-group"><label for="years">Time horizon · years</label><input id="years" type="number" value="10" min="1" max="50" step="1"></div><div class="input-group"><label for="rate">Hypothetical annual return · %</label><input id="rate" type="number" value="4" min="-50" max="30" step=".5"><small>A constant assumption, not a forecast. Try a negative return to explore losses.</small></div><div id="lab-error" role="alert"></div></section><section class="panel results-panel" id="growth-results"></section></div><section class="panel article page-content"><h2>The cost of crossing currencies</h2><p>See a simplified CAD → USD → CAD scenario. Assume the exchange rate stays the same and a conversion fee is applied to the amount converted on each leg. Actual charges depend on the broker’s exchange rate and account setup.</p><div class="content-grid"><div><label for="fx-amount">Starting investment · CAD</label><input type="number" id="fx-amount" value="100" min="0" max="10000000"><label for="fx-return" style="margin-top:15px">Investment return before FX fees · %</label><input type="number" id="fx-return" value="0" min="-100" max="1000"><label for="fx-fee" style="margin-top:15px">Conversion fee, each way · %</label><input type="number" id="fx-fee" value="1.5" min="0" max="10" step=".1"></div><div id="fx-results"></div></div><p class="source-note">The 1.5% example reflects Wealthsimple’s standard CAD-account conversion fee. Account plans and conversion tiers may differ. <a href="https://www.wealthsimple.com/en-ca/legal/fees/trade" target="_blank" rel="noopener">Check current fees ↗</a></p></section>`;updateGrowth();updateFx()}
function readNumber(id){const el=$(id);if(el.value.trim()===''||!el.checkValidity())throw new Error('Enter valid values within the shown limits.');return Number(el.value)}
function updateGrowth(){try{const result=projectGrowth(readNumber('#initial'),readNumber('#monthly'),readNumber('#years'),readNumber('#rate'));$('#lab-error').textContent='';const min=Math.min(...result.points),max=Math.max(...result.points),range=max-min||1;const d=path(result.points,650,170,6);$('#growth-results').innerHTML=`<p class="eyebrow">HYPOTHETICAL ENDING VALUE</p><div class="result-number">${money(result.balance)}</div><span class="risk-chip">Scenario only · not a forecast</span><div class="result-legend"><span>Your contributions<strong>${money(result.contributions)}</strong></span><span>Hypothetical gain / loss<strong>${money(result.balance-result.contributions)}</strong></span></div><svg class="scenario-chart" viewBox="0 0 700 215" role="img" aria-label="Hypothetical balance over ${$('#years').value} years, ending at ${money(result.balance)}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#bfdb9b" stop-opacity=".5"/><stop offset="1" stop-color="#bfdb9b" stop-opacity="0"/></linearGradient></defs><path d="M20 45H680M20 105H680M20 180H680" stroke="#e8eee2" stroke-dasharray="3 5"/><g transform="translate(20 10)"><path d="${d} L650,180 L0,180 Z" fill="url(#chart-fill)"/><path d="${d}" fill="none" stroke="#66894c" stroke-width="2.5"/></g><text x="20" y="210" fill="#8a9582" font-size="13">Today</text><text x="600" y="210" fill="#8a9582" font-size="13">Year ${$('#years').value}</text></svg><p class="explainer">This calculation compounds a fixed annual return monthly, with contributions at each month’s end. It excludes fees, taxes, and inflation. Real markets fluctuate, and you may finish with less than you invest.</p>`}catch(e){$('#lab-error').className='error-text';$('#lab-error').textContent=e.message;$('#growth-results').innerHTML='<p class="explainer">Update the inputs to see a valid scenario.</p>'}}
function updateFx(){try{const r=roundTrip(readNumber('#fx-amount'),readNumber('#fx-return'),readNumber('#fx-fee'));$('#fx-results').innerHTML=`<p class="eyebrow">AFTER BOTH CONVERSIONS</p><div class="result-number">${money(r.net)}</div><div class="status-list"><div><span>Conversion cost vs. no fees</span><strong>${money(r.cost)}</strong></div><div><span>Net gain / loss</span><strong>${money(r.profit)}</strong></div><div><span>Return needed to break even</span><strong>${r.breakEven.toFixed(2)}%</strong></div></div><p class="source-note">Excludes spreads, commissions, taxes, and changes in CAD/USD. The break-even return assumes the same FX fee on both conversions.</p>`}catch{$('#fx-results').innerHTML='<p class="error-text">Enter valid amounts, a return of at least −100%, and a fee between 0% and 10%.</p>'}}
function renderLearn(){$('#main').innerHTML=heading('FIND YOUR FOOTING','A little knowledge. A stronger start.','Plain-language explanations to help you ask better questions before you invest.')+`<div class="content-grid"><article class="panel article"><p class="eyebrow">01 / OPPORTUNITIES</p><h2>A signal is a question, not an answer.</h2><p>A rising price describes what has happened. It does not tell you what happens next. Look at earnings, valuation, debt, and what could go wrong. For a fund, understand its holdings, fees, and how closely it follows its benchmark.</p></article><article class="panel article"><p class="eyebrow">02 / RISK</p><h2>Protect the money you need soon.</h2><p>Stocks can fall when you need to withdraw. Consider your essential expenses, emergency savings, and expensive debt before deciding how much you can afford to invest. Money needed soon generally requires a different approach from long-term savings.</p><p class="source-note"><a href="https://www.getsmarteraboutmoney.ca/learning-path/getting-started/tips-for-first-time-investors/" target="_blank" rel="noopener">OSC: tips for new investors ↗</a></p></article><article class="panel article"><p class="eyebrow">03 / DIVERSIFICATION</p><h2>Spread the sources of risk.</h2><p>Holding different companies, sectors, and countries can reduce dependence on any one investment. An ETF may hold many assets, but some funds are concentrated. Read its holdings; diversification does not eliminate the possibility of losing money.</p><p class="source-note"><a href="https://www.getsmarteraboutmoney.ca/learning-path/understanding-risk/diversification/" target="_blank" rel="noopener">OSC: understanding diversification ↗</a></p></article><article class="panel article"><p class="eyebrow">04 / MODELS</p><h2>Make the math show its work.</h2><p>Momentum measures a past price change. Volatility measures how much returns vary. Drawdown measures a fall from a previous peak. None is a probability of profit. A credible model needs out-of-sample testing, realistic fees, adjusted prices, and checks for missing or stale data.</p></article><article class="panel article"><p class="eyebrow">05 / COSTS</p><h2>Small fees deserve a close look.</h2><p>Compare fund expenses, spreads, currency conversion, and subscription costs. A CAD-listed fund holding U.S. shares can avoid a direct USD purchase conversion, but can still have currency exposure, fund expenses, and tax considerations.</p><p class="source-note"><a href="#lab">Explore the fee calculator ↗</a></p></article><article class="panel article"><p class="eyebrow">06 / OUR DATA</p><h2>Know what you’re looking at.</h2><p>This version uses invented prices and synthetic historical series to demonstrate the research experience. Asset descriptions are general research context. These research examples are separate from the Overview paper pilot, which uses public CAD crypto data. No brokerage is connected.</p><p class="source-note"><a href="#connections">See connection readiness ↗</a></p></article></div>`}
function renderConnections(){$('#main').innerHTML=heading('DATA & CONNECTIONS','Trust starts with the source.','A clear view of what’s connected, what’s illustrative, and what comes next.')+`<section class="panel connection-large"><div class="connection-logo">Wealthsimple<span class="status-label">Not connected</span></div><h2>Start with a read-only view.</h2><p class="explainer">SnapTrade currently lists Wealthsimple support for account data and trading. It is a third-party integration, not a verified public Wealthsimple developer API. Before linking a real account, we need a secure server, provider credentials, and confirmation of the available permissions and pricing.</p><div class="status-strip">Connection setup is not active. This app does not collect your Wealthsimple password or place trades.</div><div class="status-list"><div><span>Brokerage connection</span><strong>Not configured</strong></div><div><span>Canadian & U.S. market feeds</span><strong>Not connected</strong></div><div><span>Background scans & alerts</span><strong>Not running</strong></div><div><span>Model validation</span><strong>Synthetic examples only</strong></div><div><span>Watchlist storage</span><strong>This browser only</strong></div></div><div class="connection-steps"><a class="button dark" href="https://docs.snaptrade.com/docs/broker-access-guide" target="_blank" rel="noopener">Review integration support ↗</a><a class="button outlined" href="https://www.wealthsimple.com/en-ca/legal/fees/trade" target="_blank" rel="noopener">Check Wealthsimple fees ↗</a></div><p class="source-note">Sources reviewed September 23, 2026. Provider capabilities and fees can change. Wealthsimple Invest / robo-advisor accounts are not supported by the listed SnapTrade integration.</p></section><section class="panel article page-content" style="max-width:760px"><h2>The path to reliable live research</h2><ul><li>Connect a licensed feed with verified TSX, TSXV, and U.S. coverage.</li><li>Show source, timestamp, currency, and quote delay for every observation.</li><li>Reject missing, stale, or invalid data before producing a signal.</li><li>Use adjusted history and test models against unseen data after costs.</li><li>Run scheduled scans on a server and report failures explicitly.</li></ul></section>`}
function navigate(){unmountPilot();currentPage=location.hash.slice(1)||'overview';if(!['overview','discover','watchlist','lab','learn','connections'].includes(currentPage))currentPage='overview';const titles={overview:'Overview',discover:'Discover',watchlist:'Watchlist',lab:'Investing lab',learn:'Learn the basics',connections:'Connections'};$('#crumb').textContent=titles[currentPage];document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===currentPage);if(a.dataset.page===currentPage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('.demo-pill').textContent=currentPage==='overview'?'Paper trading · no real money':'Research examples';if(currentPage==='overview'){mountPilot()}else({discover:renderDiscover,watchlist:renderWatchlist,lab:renderLab,learn:renderLearn,connections:liveConnections}[currentPage])();document.title=`${titles[currentPage]} · Northstar`;window.scrollTo(0,0)}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]'),detail=e.target.closest('[data-detail]'),filter=e.target.closest('[data-market]');if(save)toggleSave(save.dataset.save);if(detail)showDetail(detail.dataset.detail);if(filter){market=filter.dataset.market;renderOpportunities()}if(e.target.closest('.close-dialog'))$('#detail').close();if(e.target.closest('#help')){location.hash='connections'}});
document.addEventListener('input',e=>{if(e.target.id==='search')filterDiscovery();if(['initial','monthly','years','rate'].includes(e.target.id))updateGrowth();if(['fx-amount','fx-return','fx-fee'].includes(e.target.id))updateFx()});document.addEventListener('change',e=>{if(['market-filter','type-filter'].includes(e.target.id))filterDiscovery()});$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});window.addEventListener('hashchange',navigate);updateCount();navigate();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
 register({name:'read_research_watchlist',description:'Read the symbols saved in this browser. All market figures in this app are illustrative.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({symbols:[...saved],dataMode:'synthetic'})});
 register({name:'save_research_asset',description:'Save a supported sample asset to the local browser watchlist. Does not place a trade.',inputSchema:{type:'object',properties:{symbol:{type:'string',enum:stocks.map(s=>s.symbol)}},required:['symbol'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.symbol!=='string'||!stocks.some(s=>s.symbol===input.symbol))throw new Error('Unknown asset symbol');if(!saved.includes(input.symbol))toggleSave(input.symbol);return {symbol:input.symbol,saved:true,storage:'local browser',dataMode:'synthetic'}}});
}
